WITH recent_customers AS (SELECT * FROM customers WHERE country != 'US'), agg AS (SELECT country, DATE_TRUNC('MONTH', signup_date) AS signup_month, ROUND(AVG(age), 2) AS avg_age, ROUND(STDDEV(credit_limit), 2) AS stddev_credit_limit FROM recent_customers GROUP BY country, DATE_TRUNC('MONTH', signup_date)) SELECT country, signup_month, avg_age, stddev_credit_limit FROM agg ORDER BY country, 4 DESC;
